            if (parent.isValid())
                return;
            for (int i = start; i <= end; ++i) {
                const QModelIndex idx = model->index(i, 0);
                if (!idx.data(IssueModel::ClosedRole).toBool())
                    m_total -= idx.data(IssueModel::EstimateRole).toInt();
            }
            emit totalChanged(m_total);
        });
        connect(model, &IssueModel::dataChanged, this, [this](const QModelIndex &, const QModelIndex &, const QVector<int> &roles) {
            for (int role : roles) {
                if (role == IssueModel::EstimateRole || role == IssueModel::ClosedRole) {
                    recalculate();
                    emit totalChanged(m_total);
                    return;
                }
            }
        });
        connect(model, &IssueModel::layoutAboutToBeReset, this, [this]() {
            m_total = 0;
        });
        connect(model, &IssueModel::layoutChanged, this, [this]() {
            recalculate();
            emit totalChanged(m_total);
        });
    }
}

void BacklogSummary::recalculate()
{
    m_total = 0;
    IssueModel *model = qobject_cast<IssueModel *>(parent());
    if (!model)
        return;
    for (int i = 0; i < model->rowCount(); ++i) {
        const QModelIndex idx = model->index(i, 0);
        if (!idx.data(IssueModel::ClosedRole).toBool())
            m_total += idx.data(IssueModel::EstimateRole).toInt();
    }
}

IssueModel *BacklogSummary::model() const
{
    return qobject_cast<IssueModel *>(parent());
}

int BacklogSummary::openMinutes() const
{
    return m_total;
}

